export const getCreateStaffUserUrl = () => {




  return `/api/admin/users`
}

/**
 * @summary Create staff user (admin)
 */
export const createStaffUser = async (staffUserInput: StaffUserInput, options?: RequestInit): Promise<StaffUser> => {

  return customFetch<StaffUser>(getCreateStaffUserUrl(),
  {
    ...options,
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...options?.headers },
    body: JSON.stringify(staffUserInput)
  }
);}





export const getCreateStaffUserMutationOptions = <TError = ErrorType<unknown>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof createStaffUser>>, TError,{data: BodyType<StaffUserInput>}, TContext>, request?: SecondParameter<typeof customFetch>}
): UseMutationOptions<Awaited<ReturnType<typeof createStaffUser>>, TError,{data: BodyType<StaffUserInput>}, TContext> => {

const mutationKey = ['createStaffUser'];
const {mutation: mutationOptions, request: requestOptions} = options ?
      options.mutation && 'mutationKey' in options.mutation && options.mutation.mutationKey ?
      options
      : {...options, mutation: {...options.mutation, mutationKey}}
      : {mutation: { mutationKey, }, request: undefined};




      const mutationFn: MutationFunction<Awaited<ReturnType<typeof createStaffUser>>, {data: BodyType<StaffUserInput>}> = (props) => {
          const {data} = props ?? {};

          return  createStaffUser(data,requestOptions)
        }






  return  { mutationFn, ...mutationOptions }}

    export type CreateStaffUserMutationResult = NonNullable<Awaited<ReturnType<typeof createStaffUser>>>
    export type CreateStaffUserMutationBody = BodyType<StaffUserInput>
    export type CreateStaffUserMutationError = ErrorType<unknown>

    /**
 * @summary Create staff user (admin)
 */
export const useCreateStaffUser = <TError = ErrorType<unknown>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof createStaffUser>>, TError,{data: BodyType<StaffUserInput>}, TContext>, request?: SecondParameter<typeof customFetch>}
 ): UseMutationResult<
        Awaited<ReturnType<typeof createStaffUser>>,
        TError,
        {data: BodyType<StaffUserInput>},
        TContext
      > => {
      return useMutation(getCreateStaffUserMutationOptions(options));
    }

